/*
ST. HUBERT MEDICAL CENTER
MASTER ANALYTICS LAYER IMPLEMENTATION
Target: MySQL 8.0.46
Source: st_hubert_curated
Target: st_hubert_analytics

PURPOSE
1. Validate that the analytics schema contains the expected 23 base tables.
2. Populate empty entity tables and resume partially populated tables without duplicating primary keys.
3. Copy all 23 curated entities into the corresponding analytics tables.
4. Create reusable analytical views for clinical, operational, financial,
   workforce, pharmacy, and inventory reporting.

SAFETY
- Does not modify st_hubert_staging or st_hubert_curated.
- Does not DROP or TRUNCATE any table.
- Entity copies skip tables that already contain rows.
- INVN is copied in 25,000-ID primary-key ranges. Each statement inserts
  only keys missing from analytics, allowing safe reruns after interruption.
- The inventory copy is large (90,731,353 rows) and may take substantial
  time and disk space.
- Bed occupancy, bed turnover interval, CMI, discharge delay, and bed
  turnaround time are NOT fabricated: the current source schema does not
  contain the required bed-status, DRG-weight, discharge-order, or EVS
  sanitation timestamps.
*/

USE `st_hubert_analytics`;

SET SESSION sql_safe_updates = 0;
SET SESSION time_zone = '+00:00';

/* Align this target column with the curated source precision.
   The uploaded analytics DDL had DECIMAL(12,2), while the verified
   curated source uses DECIMAL(21,13). This prevents precision loss. */
ALTER TABLE `vpmt`
    MODIFY COLUMN `PMNT_DUE` DECIMAL(21,13) DEFAULT NULL;

/* Curated BILL stores BTYPE_CD as text (e.g., 'RG'), not an integer. */
ALTER TABLE `bill`
    MODIFY COLUMN `BTYPE_CD` VARCHAR(20) DEFAULT NULL;

/* Curated MDBL also stores BTYPE_CD as text (VARCHAR(2));
   the original analytics DDL incorrectly defined it as INT. */
ALTER TABLE `mdbl`
    MODIFY COLUMN `BTYPE_CD` VARCHAR(20) DEFAULT NULL;

/*
  RESUMABLE TABLE-BY-TABLE COPY
  Each target table is populated only when it is empty.
  Tables already loaded in a previous execution are skipped.
  This safely resumes after a statement-level error.
*/

/* Reference and parent entities */

/* Dependent reference entities */

/* Clinical and patient activity */

/* Financial and vendor transactions */

/* Largest table: resumable primary-key range batches.
   Source INVN_ID range: 1 through 93,944,165.
   Each statement copies only missing keys in a 25,000-ID range.
   With autocommit enabled, each batch commits independently.
   If execution stops, rerun this file: completed keys are skipped.
   The target primary key prevents duplicate inventory records. */

/* Post-copy count comparison: analytics_rows must equal curated_rows. */
SELECT 'ALGY' AS entity, (SELECT COUNT(*) FROM st_hubert_analytics.algy) AS analytics_rows, (SELECT COUNT(*) FROM st_hubert_curated.algy) AS curated_rows
UNION ALL SELECT 'APPT',(SELECT COUNT(*) FROM st_hubert_analytics.appt),(SELECT COUNT(*) FROM st_hubert_curated.appt)
UNION ALL SELECT 'BILL',(SELECT COUNT(*) FROM st_hubert_analytics.bill),(SELECT COUNT(*) FROM st_hubert_curated.bill)
UNION ALL SELECT 'DIAG',(SELECT COUNT(*) FROM st_hubert_analytics.diag),(SELECT COUNT(*) FROM st_hubert_curated.diag)
UNION ALL SELECT 'DPMT',(SELECT COUNT(*) FROM st_hubert_analytics.dpmt),(SELECT COUNT(*) FROM st_hubert_curated.dpmt)
UNION ALL SELECT 'EQPM',(SELECT COUNT(*) FROM st_hubert_analytics.eqpm),(SELECT COUNT(*) FROM st_hubert_curated.eqpm)
UNION ALL SELECT 'INSR',(SELECT COUNT(*) FROM st_hubert_analytics.insr),(SELECT COUNT(*) FROM st_hubert_curated.insr)
UNION ALL SELECT 'INVN',(SELECT COUNT(*) FROM st_hubert_analytics.invn),(SELECT COUNT(*) FROM st_hubert_curated.invn)
UNION ALL SELECT 'MATERIAL',(SELECT COUNT(*) FROM st_hubert_analytics.material),(SELECT COUNT(*) FROM st_hubert_curated.material)
UNION ALL SELECT 'MDBL',(SELECT COUNT(*) FROM st_hubert_analytics.mdbl),(SELECT COUNT(*) FROM st_hubert_curated.mdbl)
UNION ALL SELECT 'MDCN',(SELECT COUNT(*) FROM st_hubert_analytics.mdcn),(SELECT COUNT(*) FROM st_hubert_curated.mdcn)
UNION ALL SELECT 'MEDT',(SELECT COUNT(*) FROM st_hubert_analytics.medt),(SELECT COUNT(*) FROM st_hubert_curated.medt)
UNION ALL SELECT 'PATN',(SELECT COUNT(*) FROM st_hubert_analytics.patn),(SELECT COUNT(*) FROM st_hubert_curated.patn)
UNION ALL SELECT 'PMNT',(SELECT COUNT(*) FROM st_hubert_analytics.pmnt),(SELECT COUNT(*) FROM st_hubert_curated.pmnt)
UNION ALL SELECT 'PTAL',(SELECT COUNT(*) FROM st_hubert_analytics.ptal),(SELECT COUNT(*) FROM st_hubert_curated.ptal)
UNION ALL SELECT 'ROMS',(SELECT COUNT(*) FROM st_hubert_analytics.roms),(SELECT COUNT(*) FROM st_hubert_curated.roms)
UNION ALL SELECT 'SPLY',(SELECT COUNT(*) FROM st_hubert_analytics.sply),(SELECT COUNT(*) FROM st_hubert_curated.sply)
UNION ALL SELECT 'STFF',(SELECT COUNT(*) FROM st_hubert_analytics.stff),(SELECT COUNT(*) FROM st_hubert_curated.stff)
UNION ALL SELECT 'TMMD',(SELECT COUNT(*) FROM st_hubert_analytics.tmmd),(SELECT COUNT(*) FROM st_hubert_curated.tmmd)
UNION ALL SELECT 'TRTM',(SELECT COUNT(*) FROM st_hubert_analytics.trtm),(SELECT COUNT(*) FROM st_hubert_curated.trtm)
UNION ALL SELECT 'VIST',(SELECT COUNT(*) FROM st_hubert_analytics.vist),(SELECT COUNT(*) FROM st_hubert_curated.vist)
UNION ALL SELECT 'VNDR',(SELECT COUNT(*) FROM st_hubert_analytics.vndr),(SELECT COUNT(*) FROM st_hubert_curated.vndr)
UNION ALL SELECT 'VPMT',(SELECT COUNT(*) FROM st_hubert_analytics.vpmt),(SELECT COUNT(*) FROM st_hubert_curated.vpmt)
ORDER BY entity;

/* -------------------------------------------------------------------------
   ANALYTICAL VIEWS
   These views read from the analytics base tables and do not duplicate data.
   ------------------------------------------------------------------------- */

/* 1. Visit-level length of stay.
   Duration is measured in days from VIS_EN to VIS_EX.
   Rows with missing or reversed timestamps are excluded from LOS. */
CREATE OR REPLACE VIEW `vw_visit_los` AS
SELECT
    v.VISIT_ID,
    v.REFR_NO,
    v.PAT_ID,
    v.MEDT_ID,
    v.ROM_ID,
    v.VIS_EN,
    v.VIS_EX,
    v.VSTAT_CD,
    v.VSTAT_DES,
    v.VTYPE_CD,
    v.VTYPE_DES,
    CASE
        WHEN v.VIS_EN IS NOT NULL
         AND v.VIS_EX IS NOT NULL
         AND v.VIS_EX >= v.VIS_EN
        THEN ROUND(TIMESTAMPDIFF(SECOND, v.VIS_EN, v.VIS_EX) / 86400, 4)
        ELSE NULL
    END AS LOS_DAYS,
    CASE
        WHEN v.VIS_EN IS NOT NULL
         AND v.VIS_EX IS NOT NULL
         AND v.VIS_EX >= v.VIS_EN
        THEN TIMESTAMPDIFF(HOUR, v.VIS_EN, v.VIS_EX)
        ELSE NULL
    END AS LOS_HOURS
FROM vist v;

/* 2. Daily visit/admission and exit flow.
   Counts are visit records, not unique patients. */
CREATE OR REPLACE VIEW `vw_daily_patient_flow` AS
SELECT
    DATE(VIS_EN) AS flow_date,
    COUNT(*) AS visit_entries,
    COUNT(DISTINCT PAT_ID) AS distinct_patients_entered
FROM vist
WHERE VIS_EN IS NOT NULL
GROUP BY DATE(VIS_EN);

/* 3. Daily recorded visit exits. */
CREATE OR REPLACE VIEW `vw_daily_visit_exits` AS
SELECT
    DATE(VIS_EX) AS exit_date,
    COUNT(*) AS visit_exits,
    COUNT(DISTINCT PAT_ID) AS distinct_patients_exited
FROM vist
WHERE VIS_EX IS NOT NULL
GROUP BY DATE(VIS_EX);

/* 4. Patient-level 30-day subsequent-visit indicator.
   This is a visit-based proxy: a subsequent visit within 30 days after
   the prior VIS_EX. It is not a validated unplanned inpatient readmission
   measure because the source has no admission class or planned/unplanned flag. */
CREATE OR REPLACE VIEW `vw_patient_30d_subsequent_visit` AS
WITH ordered_visits AS (
    SELECT
        v.VISIT_ID,
        v.PAT_ID,
        v.REFR_NO,
        v.VIS_EN,
        v.VIS_EX,
        LEAD(v.VIS_EN) OVER (
            PARTITION BY v.PAT_ID
            ORDER BY v.VIS_EN, v.VISIT_ID
        ) AS NEXT_VISIT_EN
    FROM vist v
    WHERE v.PAT_ID IS NOT NULL
)
SELECT
    VISIT_ID,
    PAT_ID,
    REFR_NO,
    VIS_EN,
    VIS_EX,
    NEXT_VISIT_EN,
    CASE
        WHEN VIS_EX IS NOT NULL
         AND NEXT_VISIT_EN IS NOT NULL
         AND NEXT_VISIT_EN >= VIS_EX
         AND NEXT_VISIT_EN <= DATE_ADD(VIS_EX, INTERVAL 30 DAY)
        THEN 1 ELSE 0
    END AS SUBSEQUENT_VISIT_WITHIN_30D,
    CASE
        WHEN VIS_EX IS NOT NULL AND NEXT_VISIT_EN IS NOT NULL
         AND NEXT_VISIT_EN >= VIS_EX
        THEN TIMESTAMPDIFF(DAY, VIS_EX, NEXT_VISIT_EN)
        ELSE NULL
    END AS DAYS_TO_NEXT_VISIT
FROM ordered_visits;

/* 5. Patient-level summary of visit-based 30-day subsequent visits. */
CREATE OR REPLACE VIEW `vw_patient_30d_visit_summary` AS
SELECT
    PAT_ID,
    COUNT(*) AS eligible_completed_visits,
    SUM(SUBSEQUENT_VISIT_WITHIN_30D) AS visits_followed_by_30d_subsequent_visit,
    ROUND(
        100.0 * SUM(SUBSEQUENT_VISIT_WITHIN_30D) / NULLIF(COUNT(*), 0),
        2
    ) AS pct_visits_followed_by_30d_subsequent_visit
FROM vw_patient_30d_subsequent_visit
WHERE VIS_EX IS NOT NULL
GROUP BY PAT_ID;

/* 6. Clinical diagnosis profile by diagnosis code and description. */
CREATE OR REPLACE VIEW `vw_diagnosis_profile` AS
SELECT
    DIG_CD,
    DIG_DES,
    DSTAT_CD,
    DSTAT_DES,
    DTYPE_CD,
    DTYPE_DES,
    COUNT(*) AS diagnosis_records,
    COUNT(DISTINCT REFR_NO) AS distinct_visit_references,
    SUM(COALESCE(DIG_TOT, 0)) AS recorded_diagnosis_cost
FROM diag
GROUP BY
    DIG_CD, DIG_DES, DSTAT_CD, DSTAT_DES, DTYPE_CD, DTYPE_DES;

/* 7. Treatment activity by treatment category, specialty, and status. */
CREATE OR REPLACE VIEW `vw_treatment_activity` AS
SELECT
    TTYPE_CD,
    TTYPE_DES,
    TRTM_CD,
    TRTM_DES,
    TSTAT_CD,
    TSTAT_DES,
    COUNT(*) AS treatment_records,
    COUNT(DISTINCT REFR_NO) AS distinct_visit_references,
    SUM(COALESCE(TRTM_TOT, 0)) AS recorded_treatment_cost
FROM trtm
GROUP BY TTYPE_CD, TTYPE_DES, TRTM_CD, TRTM_DES, TSTAT_CD, TSTAT_DES;

/* 8. Medication utilization by medicine. */
CREATE OR REPLACE VIEW `vw_medication_utilization` AS
SELECT
    m.MED_ID,
    m.MED_NAME,
    m.TYPE_DES AS medicine_type,
    m.FORM_DES AS dosage_form,
    COUNT(t.TMMD_ID) AS prescription_lines,
    COUNT(DISTINCT t.REFR_NO) AS distinct_visit_references,
    SUM(COALESCE(t.QTY_NO, 0)) AS total_quantity_recorded
FROM mdcn m
LEFT JOIN tmmd t ON t.MED_ID = m.MED_ID
GROUP BY m.MED_ID, m.MED_NAME, m.TYPE_DES, m.FORM_DES;

/* 9. Department workforce profile.
   STFF may contain multiple records per STF_ID; count distinct staff IDs. */
CREATE OR REPLACE VIEW `vw_department_workforce` AS
SELECT
    d.DEP_ID,
    d.DEP_NAME,
    d.DEP_LOC,
    COUNT(DISTINCT s.STF_ID) AS distinct_staff_members,
    COUNT(s.STAFF_RECORD_ID) AS staff_records,
    SUM(COALESCE(s.SAL_YR, 0)) AS sum_recorded_annual_salary,
    SUM(COALESCE(s.SAL_MN, 0)) AS sum_recorded_monthly_salary
FROM dpmt d
LEFT JOIN stff s ON s.DEP_ID = d.DEP_ID
GROUP BY d.DEP_ID, d.DEP_NAME, d.DEP_LOC;

/* 10. Appointment volume by date, type, and status. */
CREATE OR REPLACE VIEW `vw_appointment_trends` AS
SELECT
    DATE(APT_TIME) AS appointment_date,
    ATYPE_CD,
    ATYPE_DES,
    ASTAT_CD,
    ASTAT_DES,
    COUNT(*) AS appointment_count,
    COUNT(DISTINCT PAT_ID) AS distinct_patients
FROM appt
WHERE APT_TIME IS NOT NULL
GROUP BY DATE(APT_TIME), ATYPE_CD, ATYPE_DES, ASTAT_CD, ASTAT_DES;

/* 11. Billing summary by billing date and status. */
CREATE OR REPLACE VIEW `vw_billing_summary` AS
SELECT
    BILL_DATE,
    BSTAT_CD,
    BSTAT_DES,
    BTYPE_CD,
    COUNT(*) AS bill_count,
    COUNT(DISTINCT PAT_ID) AS distinct_patients_billed,
    SUM(COALESCE(BILL_AMT, 0)) AS total_billed_amount,
    AVG(BILL_AMT) AS average_bill_amount
FROM bill
GROUP BY BILL_DATE, BSTAT_CD, BSTAT_DES, BTYPE_CD;

/* 12. Patient payment summary by date and method. */
CREATE OR REPLACE VIEW `vw_patient_payment_summary` AS
SELECT
    PMNT_DATE,
    METH_CD,
    METH_DES,
    PSTAT_CD,
    PSTAT_DES,
    COUNT(*) AS payment_records,
    COUNT(DISTINCT PAT_ID) AS distinct_paying_patients,
    SUM(COALESCE(PMNT_AMT, 0)) AS total_payment_amount
FROM pmnt
GROUP BY PMNT_DATE, METH_CD, METH_DES, PSTAT_CD, PSTAT_DES;

/* 13. Insurance coverage profile. */
CREATE OR REPLACE VIEW `vw_insurance_coverage` AS
SELECT
    COM_NAME,
    ITYPE_CD,
    ITYPE_DES,
    ISTAT_CD,
    ISTAT_DES,
    COUNT(*) AS policy_count,
    COUNT(DISTINCT PAT_ID) AS covered_patients,
    MIN(POL_ST) AS earliest_policy_start,
    MAX(POL_ED) AS latest_policy_end
FROM insr
GROUP BY COM_NAME, ITYPE_CD, ITYPE_DES, ISTAT_CD, ISTAT_DES;

/* 14. Vendor payment exposure. */
CREATE OR REPLACE VIEW `vw_vendor_payment_summary` AS
SELECT
    v.VEN_ACC,
    v.VEN_NAME,
    v.VEN_TYPE,
    v.CTRY_NAME,
    p.VPSTATUS_CD,
    p.VPSTATUS_DES,
    COUNT(*) AS payment_terms,
    SUM(COALESCE(p.VPMT_AMT, 0)) AS total_payment_amount,
    SUM(COALESCE(p.PMNT_DUE, 0)) AS total_remaining_due
FROM vndr v
JOIN vpmt p ON p.VEN_ACC = v.VEN_ACC
GROUP BY
    v.VEN_ACC, v.VEN_NAME, v.VEN_TYPE, v.CTRY_NAME,
    p.VPSTATUS_CD, p.VPSTATUS_DES;

/* 15. Inventory movement by date and material SKU.
   This is an aggregate of recorded movement quantities, not a live stock
   balance unless the source's OPEN/RCVD/ISSD/CLSD semantics are confirmed. */
CREATE OR REPLACE VIEW `vw_inventory_daily_movement` AS
SELECT
    DATE(INGTN_TS) AS movement_date,
    MAT_SKU,
    COUNT(*) AS inventory_records,
    SUM(COALESCE(OPEN_QTY, 0)) AS opening_quantity,
    SUM(COALESCE(RCVD_QTY, 0)) AS received_quantity,
    SUM(COALESCE(ISSD_QTY, 0)) AS issued_quantity,
    SUM(COALESCE(CLSD_QTY, 0)) AS closed_quantity
FROM invn
GROUP BY DATE(INGTN_TS), MAT_SKU;

/* 16. Supply procurement profile by vendor and material. */
CREATE OR REPLACE VIEW `vw_supply_procurement` AS
SELECT
    s.VEN_ACC,
    v.VEN_NAME,
    s.MATERIAL_ID,
    m.MATERIAL_TYPE,
    m.SOURCE_MAT_SKU,
    COUNT(*) AS supply_lots,
    SUM(COALESCE(s.SPL_QTY, 0)) AS total_supplied_quantity,
    SUM(COALESCE(s.SPL_QTY, 0) * COALESCE(s.SPL_UCT, 0)) AS estimated_supply_value,
    SUM(COALESCE(s.RCVD_QTY, 0)) AS total_received_quantity
FROM sply s
LEFT JOIN vndr v ON v.VEN_ACC = s.VEN_ACC
LEFT JOIN material m ON m.MATERIAL_ID = s.MATERIAL_ID
GROUP BY
    s.VEN_ACC, v.VEN_NAME, s.MATERIAL_ID,
    m.MATERIAL_TYPE, m.SOURCE_MAT_SKU;

/* 17. Room capacity reference. This reports configured capacity only.
   It is NOT an occupancy-rate calculation. */
CREATE OR REPLACE VIEW `vw_room_capacity_reference` AS
SELECT
    r.DEP_ID,
    d.DEP_NAME,
    r.ROM_ID,
    r.PRPS_DES AS room_purpose,
    r.RTYPE_DES AS room_type,
    r.CPCT_NO AS configured_capacity
FROM roms r
LEFT JOIN dpmt d ON d.DEP_ID = r.DEP_ID;

/* -------------------------------------------------------------------------
   POST-LOAD VALIDATION
   The first result set compares row counts in analytics and curated.
   The second lists all analytical views created by this script.
   ------------------------------------------------------------------------- */

SELECT 'ALGY' AS entity,
       (SELECT COUNT(*) FROM st_hubert_curated.algy) AS curated_rows,
       (SELECT COUNT(*) FROM st_hubert_analytics.algy) AS analytics_rows
UNION ALL SELECT 'APPT',(SELECT COUNT(*) FROM st_hubert_curated.appt),(SELECT COUNT(*) FROM st_hubert_analytics.appt)
UNION ALL SELECT 'BILL',(SELECT COUNT(*) FROM st_hubert_curated.bill),(SELECT COUNT(*) FROM st_hubert_analytics.bill)
UNION ALL SELECT 'DIAG',(SELECT COUNT(*) FROM st_hubert_curated.diag),(SELECT COUNT(*) FROM st_hubert_analytics.diag)
UNION ALL SELECT 'DPMT',(SELECT COUNT(*) FROM st_hubert_curated.dpmt),(SELECT COUNT(*) FROM st_hubert_analytics.dpmt)
UNION ALL SELECT 'EQPM',(SELECT COUNT(*) FROM st_hubert_curated.eqpm),(SELECT COUNT(*) FROM st_hubert_analytics.eqpm)
UNION ALL SELECT 'INSR',(SELECT COUNT(*) FROM st_hubert_curated.insr),(SELECT COUNT(*) FROM st_hubert_analytics.insr)
UNION ALL SELECT 'INVN',(SELECT COUNT(*) FROM st_hubert_curated.invn),(SELECT COUNT(*) FROM st_hubert_analytics.invn)
UNION ALL SELECT 'MATERIAL',(SELECT COUNT(*) FROM st_hubert_curated.material),(SELECT COUNT(*) FROM st_hubert_analytics.material)
UNION ALL SELECT 'MDBL',(SELECT COUNT(*) FROM st_hubert_curated.mdbl),(SELECT COUNT(*) FROM st_hubert_analytics.mdbl)
UNION ALL SELECT 'MDCN',(SELECT COUNT(*) FROM st_hubert_curated.mdcn),(SELECT COUNT(*) FROM st_hubert_analytics.mdcn)
UNION ALL SELECT 'MEDT',(SELECT COUNT(*) FROM st_hubert_curated.medt),(SELECT COUNT(*) FROM st_hubert_analytics.medt)
UNION ALL SELECT 'PATN',(SELECT COUNT(*) FROM st_hubert_curated.patn),(SELECT COUNT(*) FROM st_hubert_analytics.patn)
UNION ALL SELECT 'PMNT',(SELECT COUNT(*) FROM st_hubert_curated.pmnt),(SELECT COUNT(*) FROM st_hubert_analytics.pmnt)
UNION ALL SELECT 'PTAL',(SELECT COUNT(*) FROM st_hubert_curated.ptal),(SELECT COUNT(*) FROM st_hubert_analytics.ptal)
UNION ALL SELECT 'ROMS',(SELECT COUNT(*) FROM st_hubert_curated.roms),(SELECT COUNT(*) FROM st_hubert_analytics.roms)
UNION ALL SELECT 'SPLY',(SELECT COUNT(*) FROM st_hubert_curated.sply),(SELECT COUNT(*) FROM st_hubert_analytics.sply)
UNION ALL SELECT 'STFF',(SELECT COUNT(*) FROM st_hubert_curated.stff),(SELECT COUNT(*) FROM st_hubert_analytics.stff)
UNION ALL SELECT 'TMMD',(SELECT COUNT(*) FROM st_hubert_curated.tmmd),(SELECT COUNT(*) FROM st_hubert_analytics.tmmd)
UNION ALL SELECT 'TRTM',(SELECT COUNT(*) FROM st_hubert_curated.trtm),(SELECT COUNT(*) FROM st_hubert_analytics.trtm)
UNION ALL SELECT 'VIST',(SELECT COUNT(*) FROM st_hubert_curated.vist),(SELECT COUNT(*) FROM st_hubert_analytics.vist)
UNION ALL SELECT 'VNDR',(SELECT COUNT(*) FROM st_hubert_curated.vndr),(SELECT COUNT(*) FROM st_hubert_analytics.vndr)
UNION ALL SELECT 'VPMT',(SELECT COUNT(*) FROM st_hubert_curated.vpmt),(SELECT COUNT(*) FROM st_hubert_analytics.vpmt)
ORDER BY entity;

SELECT
    table_name AS analytical_view
FROM information_schema.views
WHERE table_schema = 'st_hubert_analytics'
  AND table_name LIKE 'vw\\_%'
ORDER BY table_name;

SELECT
    COUNT(*) AS analytics_base_tables
FROM information_schema.tables
WHERE table_schema = 'st_hubert_analytics'
  AND table_type = 'BASE TABLE';

SELECT
    COUNT(*) AS analytics_views
FROM information_schema.views
WHERE table_schema = 'st_hubert_analytics';
